46	STATIC int urd_check_module_init(const char *module_name)
47	{
48	    char *buff = NULL;
49	    FILE *fp = NULL;
50	    size_t name_len;
51	    int retry_times = -1;
52	
53	    if (module_name == NULL) {
54	        urd_err("Para is NULL.\n");
55	        return -1;
56	    }
57	    name_len = strnlen(module_name, DEV_MODULE_INIT_INFO_LEN);
58	    if (name_len >= DEV_MODULE_INIT_INFO_LEN) {
59	        urd_err("Length out range. (length=%ld)\n", name_len);
60	        return -1;
61	    }
62	    buff = (char *)malloc(DEV_MODULE_INIT_INFO_LEN);
63	    if (buff == NULL) {
64	        urd_err("Malloc memory error. (size=%d)\n", DEV_MODULE_INIT_INFO_LEN);
65	        return -1;
66	    }
67	
68	    do {
69	        fp = fopen(PROC_MOUDULE_FILE_NAME, "r");
70	        retry_times++;
71	    } while (fp == NULL && retry_times < MAX_FOPEN_RETRY_TIMES);
72	
73	    if (fp == NULL) {
74	        urd_err("Fopen error. (file=\"%s\"; errno:%d, retry_time=%d)\n", PROC_MOUDULE_FILE_NAME, errno, retry_times);
75	        (void)free(buff);
76	        buff = NULL;
77	        return -1;
78	    }
79	    while (fgets(buff, DEV_MODULE_INIT_INFO_LEN, fp) != NULL) {
80	        if (strstr(buff, module_name) != NULL) {
81	            (void)free(buff);
82	            (void)fclose(fp);
83	            buff = NULL;
84	            fp = NULL;
85	            return 0;
86	        }
87	    }
88	
89	    (void)free(buff);
90	    (void)fclose(fp);
91	    buff = NULL;
92	    fp = NULL;
93	    return -1;
94	}
95	#endif
