102	    if (!FdIsValid(fd)) {
103	        return DRV_ERROR_INVALID_VALUE;
104	    }
105	#ifdef CFG_FEATURE_MODULE_CHECK
106	    if (urd_check_module_init("asdrv_vdms") == 0) {
107	        g_env_virt = true;
108	        return 0;
109	    }
110	#endif
