147	STATIC mmProcess urd_open_intf(void)
148	{
149	    mmProcess fd = URD_INVALID_PID_OR_FD;
150	    int err = 0;
151	    int ret = 0;
152	
153	    /* to improve performance */
154	    if (FdIsValid(g_urd_fd) && (g_urd_tgid == getpid())) {
155	        return g_urd_fd;
156	    }
157	
158	    (void)mmMutexLock(&g_urd_fd_mutex);
159	    if (FdIsValid(g_urd_fd)) {
160	        if (g_urd_tgid != getpid()) {
161	            g_urd_fd = (mmProcess)URD_INVALID_PID_OR_FD;
162	        } else {
163	            fd = g_urd_fd;
164	            goto out;
165	        }
166	    }
167	
168	    fd = mmOpen2(davinci_intf_get_dev_path(), M_RDWR | O_CLOEXEC, M_IRUSR);
169	    err = (__errno_location() != NULL ? errno : 0);
170	    if (!FdIsValid(fd)) {
171	        urd_err(
172	            "Open failed. (dev_name=%s; fd=%d; g_urd_fd=%d; errno=%d)\n", davinci_intf_get_dev_path(), fd, g_urd_fd,
173	            err);
174	        fd = (mmProcess)URD_INVALID_PID_OR_FD;
175	        goto out;
176	    }
177	    ret = urd_ioctl_open(fd);
178	    if (ret != 0) {
179	        urd_ioctl_close(fd);
180	        (void)mmClose(fd);
181	        urd_err("Urd ioctl open failed. (ret=%d; fd=%d)\n", ret, fd);
182	        fd = (mmProcess)URD_INVALID_PID_OR_FD;
183	        goto out;
184	    }
185	
186	    g_urd_fd = fd;
187	    g_urd_tgid = getpid();
188	out:
189	    (void)mmMutexUnLock(&g_urd_fd_mutex);
190	    return fd;
191	}
