193	STATIC void urd_close_intf(void)
194	{
195	    (void)mmMutexLock(&g_urd_fd_mutex);
196	    if (FdIsValid(g_urd_fd)) {
197	        if (g_urd_tgid == getpid()) {
198	            urd_ioctl_close(g_urd_fd);
199	            (void)mmClose(g_urd_fd);
200	        }
201	        g_urd_fd = (mmProcess)URD_INVALID_PID_OR_FD;
202	        g_urd_tgid = (pid_t)URD_INVALID_PID_OR_FD;
203	    }
204	    (void)mmMutexUnLock(&g_urd_fd_mutex);
205	}
