228	/*
229	    |kernel return   | ioctl return | errno |
230	    |ret=[, -4096]   | ret          |       |
231	    |ret=[-4095, -1] | -1           | |ret| |
232	    |ret=[0, ]       | ret          |       |
233	
234	    convert ioctl return/errno to userspace errno.
235	    support kernel return kernel errno(negative) or userspace errno.
236	*/
237	STATIC drvError_t urd_ioctl_errno_convert(int ret, int errno_param)
238	{
239	    /* kernel return [-4095, -1] */
240	    if (ret == -1) { /* only if ret is -1, errno is set */
241	        return errno_to_user_errno(errno_param);
242	    }
243	    /* kernel return <= -4096 or >= 0 */
244	    if (is_valid_user_errno(ret)) {
245	        return ret;
246	    }
247	    return DRV_ERROR_IOCRL_FAIL;
248	}
