250	STATIC drvError_t urd_ioctl(unsigned long cmd, struct urd_ioctl_arg *ioarg)
251	{
252	    mmProcess fd;
253	    drvError_t ret;
254	
255	    if (ioarg == NULL) {
256	        urd_err("Ioctl arg is null\n");
257	        return DRV_ERROR_PARA_ERROR;
258	    }
259	
260	    fd = urd_open_intf();
261	    if (!FdIsValid(fd)) {
262	        urd_err("Open device failed. (fd=%d)\n", fd);
263	        return DRV_ERROR_OPEN_FAILED;
264	    }
265	
266	#ifndef CFG_FEATURE_SRIOV
267	    if (g_env_virt == true) {
268	        return DRV_ERROR_NOT_SUPPORT;
269	    }
270	#endif
271	    ret = ioctl(fd, cmd, ioarg);
272	    if (ret == 0) {
273	        return 0;
274	    }
275	    ret = urd_ioctl_errno_convert(ret, errno);
276	    share_log_read_err(HAL_MODULE_TYPE_DEV_MANAGER);
277	    return ret;
278	}
