247	u32 soc_res_get_ver(u32 udevid, enum soc_ver_type type, u32 *ver)
248	{
249	    int fd = -1, ret, tmp_errno, tmp;
250	    struct davinci_intf_open_arg arg = {{0}};
251	
252	    fd = open(davinci_intf_get_dev_path(), O_RDWR | O_SYNC | O_CLOEXEC);
253	    if (fd < 0) {
254	        DRV_COMM_ERR("Open device fail. (fd=%d; chardev=%s)\n", fd, davinci_intf_get_dev_path());
255	        return fd;
256	    }
257	
258	    ret = strcpy_s(arg.module_name, DAVINIC_MODULE_NAME_MAX, SOC_RESMNG_MODULE_NAME);
259	    if (ret != 0) {
260	        DRV_COMM_ERR("Strcpy_s failed. (ret=%d)\n", ret);
261	        ret = DRV_ERROR_INNER_ERR;
262	        goto close_fd;
263	    }
264	
265	    ret = ioctl(fd, (unsigned long)DAVINCI_INTF_IOCTL_OPEN, &arg);
266	    if (ret != 0) {
267	        tmp_errno = errno;
268	        DRV_COMM_ERR("DAVINCI_INTF_IOCTL_OPEN failed. (ret=%d)\n", ret);
269	        ret = DRV_COMM_KERNEL_ERR(tmp_errno);
270	        goto davinci_close;
271	    }
272	
273	    if (type == VER_TYPE_DEV) {
274	        ret = ioctl(fd, SOC_RESMNG_GET_DEV_VER, ver);
275	        if (ret < 0) {
276	            DRV_COMM_ERR("get device version fail, (udevid=%u)\n", udevid);
277	            goto davinci_close;
278	        }
279	    } else if (type == VER_TYPE_HOST) {
280	        ret = ioctl(fd, SOC_RESMNG_GET_HOST_VER, ver);
281	        if (ret < 0) {
282	            DRV_COMM_ERR("get device version fail, (udevid=%u)\n", udevid);
283	            goto davinci_close;
284	        }
285	    } else {
286	        DRV_COMM_ERR("invalid version type, (udevid=%u)\n", udevid);
287	        ret = DRV_ERROR_INNER_ERR;
288	        goto davinci_close;
289	    }
290	
291	davinci_close:
292	    tmp = ioctl(fd, (unsigned long)DAVINCI_INTF_IOCTL_CLOSE, &arg);
293	    if (tmp != 0) {
294	        DRV_COMM_ERR("Davinci close fail. (ret=%d)\n", tmp);
295	    }
296	close_fd:
297	    tmp = close(fd);
298	    if (tmp != 0) {
299	        DRV_COMM_ERR("Close device fail. (ret=%d; fd=%d)\n", tmp, fd);
300	    }
301	    return ret;
302	}
